/* ~~/build/ograph.rs */

// standard library
use std::fs::File;
use std::io::Read;
use std::path::Path;
use std::sync::Arc;

// third-party crates
use resvg::render;
use tiny_skia::{Pixmap, Transform};
use usvg::{Options, Tree};

pub fn render_opengraph_image(count: usize, last_updated: &str) -> std::io::Result<()> {
  let mut font_db = usvg::fontdb::Database::new();
  let mut font_file = File::open("./assets/sov-prisna.ttf")?;
  let mut font_data = Vec::new();
  font_file.read_to_end(&mut font_data)?;
  font_db.load_font_data(font_data);
  font_db.load_system_fonts();
  let data = format!(
    r#"<?xml version='1.0' encoding='utf-8'?>
<svg
  height='630px'
  version='1.1'
  viewBox='0 0 1200 630'
  xmlns='http://www.w3.org/2000/svg'
  xmlns:space='preserve'
  xmlns:svgjs='http://svgjs.dev/svgjs'
  xmlns:xlink='http://www.w3.org/1999/xlink'
  width='1200px'>
  <defs>
    <filter
      height='200%'
      id='dropShadow'
      width='200%'
      x='0'
      y='0'
      >
      <feOffset
        dx='12'
        dy='12'
        in='SourceGraphic'
        result='offOut'
        />
      <feColorMatrix
        in='offOut'
        result='matrixOut'
        type='matrix'
        values='
          0.2 0 0 0 0
          0 0.2 0 0 0
          0 0 0.2 0 0
          0 0 0 0.4 0
        '/>
      <feGaussianBlur
        in='matrixOut'
        result='blurOut'
        stdDeviation='8'
        />
      <feBlend
        in='SourceGraphic'
        in2='blurOut'
        mode='normal'
        />
    </filter>
    <pattern id='icon'
      height='100%'
      patternContentUnits='userSpaceOnUse'
      viewBox='0 0 260 260'
      width='100%'
      x='0%'
      y='0%'>
      <image
        height='256px'
        href='data:image/svg+xml;base64,'
        preserveAspectRatio='none'
        width='256px'
        x='0%'
        y='0%'
        >
      </image>
    </pattern>
  </defs>
  <rect
    fill='white'
    height='100%'
    width='100%'
    x='0'
    y='0'
    />
  <rect
    fill='url(#icon)'
    filter='url(#dropShadow)'
    height='400px'
    rx='36px'
    width='400px'
    x='40px'
    y='120px'
    />
  <text
    font-family='SOV_Prisna'
    font-size='224px'
    id='title'
    transform='rotate(-16)'
    transform-origin='50% 50%'
    y='192px'>
    <tspan
      dy='32px'
      x='448px'>
      Guru's
    </tspan>
    <tspan
      dy='128px'
      x='640px'
      >
      Gazette
    </tspan>
  </text>
  <g>
    <text
      fill='#BBB'
      font-family='Arial'
      font-size='20px'
      stroke='#CCC'
      text-anchor='middle'
      x='650px'
      y='384px'>
      Last updated
    </text>
    <text
      fill='#777'
      font-family='Arial'
      font-size='42px'
      text-anchor='middle'
      x='648px'
      y='448px'>
      {last_updated}
    </text>
    <rect
      fill='none'
      filter='url(#dropShadow)'
      height='20%'
      rx='32px'
      stroke='#CCC'
      width='20%'
      x='44%'
      y='58%'
      />
  </g>
  <g>
    <text
      fill='#BBB'
      font-family='Arial'
      font-size='20px'
      stroke='#CCC'
      text-anchor='middle'
      x='982px'
      y='384px'>
      Notes
    </text>
    <text
      fill='#777'
      font-family='Arial'
      font-size='42px'
      text-anchor='middle'
      x='982px'
      y='448px'>
      {count}
    </text>
    <rect
      fill='none'
      filter='url(#dropShadow)'
      height='20%'
      rx='32px'
      stroke='#CCC'
      width='20%'
      x='72%'
      y='58%'
      />
    </g>
  <text
    font-family='Arial'
    font-size='32px'
    y='544px'>
    <tspan
      dy='0px'
      x='416px'>
      Collection of musings about of Bitcoin, Python, Rust,
    </tspan>
    <tspan
      dy='38px'
      x='416px'>
      Simplicity and WebAssembly by Aekasitt Guruvanich
    </tspan>
  </text>
</svg>"#,
  );
  let mut opt = Options::default();
  opt.fontdb = Arc::new(font_db);
  opt.font_family = String::from("SOV_Prisna");
  let tree = Tree::from_str(&data, &opt)
    .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e.to_string()))?;
  let size = tree.size();
  let mut pixmap =
    Pixmap::new(size.width() as u32, size.height() as u32).ok_or(std::io::Error::new(
      std::io::ErrorKind::InvalidData,
      "Failed to create pixel buffer",
    ))?;
  render(&tree, Transform::default(), &mut pixmap.as_mut());
  pixmap.save_png(Path::new("./assets/opengraph.png"))?;
  Ok(())
}
